// src/utils/crypto.js
// Web Crypto helpers: PBKDF2 key derivation + AES-GCM JSON encryption.
// Used by both the security gate and the storage layer.

const encoder = new TextEncoder();
const decoder = new TextDecoder();

export const PBKDF2_ITERATIONS = 310000;
export const SALT_BYTES = 16;
export const IV_BYTES = 12;
export const CIPHER_VERSION = 1;

/** True when the browser exposes the Web Crypto primitives we need. */
export function cryptoAvailable() {
  return (
    typeof crypto !== 'undefined' &&
    typeof crypto.subtle !== 'undefined' &&
    typeof crypto.getRandomValues === 'function'
  );
}

/** Cryptographically random bytes. */
export function randomBytes(length) {
  const bytes = new Uint8Array(length);
  crypto.getRandomValues(bytes);
  return bytes;
}

/** Uint8Array -> base64 (chunked so large payloads don't blow the call stack). */
export function bytesToBase64(bytes) {
  let binary = '';
  const chunkSize = 0x8000;
  for (let i = 0; i < bytes.length; i += chunkSize) {
    binary += String.fromCharCode.apply(null, bytes.subarray(i, i + chunkSize));
  }
  return btoa(binary);
}

/** base64 -> Uint8Array. */
export function base64ToBytes(base64) {
  const binary = atob(base64);
  const out = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i += 1) out[i] = binary.charCodeAt(i);
  return out;
}

/**
 * Derive an AES-GCM key from a passcode.
 * @param {string} passcode
 * @param {Uint8Array} salt
 * @param {number} iterations
 * @returns {Promise<CryptoKey>}
 */
export async function deriveKey(passcode, salt, iterations = PBKDF2_ITERATIONS) {
  const baseKey = await crypto.subtle.importKey(
    'raw',
    encoder.encode(passcode),
    'PBKDF2',
    false,
    ['deriveKey'],
  );

  return crypto.subtle.deriveKey(
    { name: 'PBKDF2', salt, iterations, hash: 'SHA-256' },
    baseKey,
    { name: 'AES-GCM', length: 256 },
    false,
    ['encrypt', 'decrypt'],
  );
}

/**
 * Encrypt any JSON-serialisable value.
 * @returns {Promise<{v:number, iv:string, ct:string}>}
 */
export async function encryptJson(key, value) {
  const iv = randomBytes(IV_BYTES);
  const plaintext = encoder.encode(JSON.stringify(value));
  const ciphertext = await crypto.subtle.encrypt({ name: 'AES-GCM', iv }, key, plaintext);
  return {
    v: CIPHER_VERSION,
    iv: bytesToBase64(iv),
    ct: bytesToBase64(new Uint8Array(ciphertext)),
  };
}

/** Decrypt a blob produced by encryptJson. Throws on tamper / wrong key. */
export async function decryptJson(key, blob) {
  if (!blob || blob.v !== CIPHER_VERSION || typeof blob.iv !== 'string' || typeof blob.ct !== 'string') {
    throw new Error('Unsupported or corrupt ciphertext');
  }
  const iv = base64ToBytes(blob.iv);
  const ciphertext = base64ToBytes(blob.ct);
  const plaintext = await crypto.subtle.decrypt({ name: 'AES-GCM', iv }, key, ciphertext);
  return JSON.parse(decoder.decode(plaintext));
}

// --- Passcode verifier ---------------------------------------------------
// We never store the passcode or the key. We store a blob that only the correct
// key can decrypt, and check that it decrypts to a known constant.

const VERIFIER_PLAINTEXT = 'ummi-vault-check-v1';

export async function makeVerifier(key) {
  return encryptJson(key, VERIFIER_PLAINTEXT);
}

export async function checkVerifier(key, blob) {
  try {
    const value = await decryptJson(key, blob);
    return value === VERIFIER_PLAINTEXT;
  } catch {
    return false;
  }
}

// src/utils/debounce.js
// Small debounce helper with cancel/flush, used by the auto-save pipeline.

/**
 * @param {Function} fn
 * @param {number} wait milliseconds
 * @returns {Function & {cancel: Function, flush: Function, pending: Function}}
 */
export function debounce(fn, wait = 400) {
  let timer = null;
  let lastArgs = null;

  const invoke = () => {
    const args = lastArgs;
    lastArgs = null;
    timer = null;
    if (args) fn(...args);
  };

  const wrapped = (...args) => {
    lastArgs = args;
    if (timer) clearTimeout(timer);
    timer = setTimeout(invoke, wait);
  };

  wrapped.cancel = () => {
    if (timer) clearTimeout(timer);
    timer = null;
    lastArgs = null;
  };

  wrapped.flush = () => {
    if (!timer) return;
    clearTimeout(timer);
    invoke();
  };

  wrapped.pending = () => timer !== null;

  return wrapped;
}

export default debounce;

// src/utils/formatSmallWinDate.js
// Consistent, local-timezone-safe date formatting for Small Wins.

const MONTHS_SHORT = [
  'Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun',
  'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec',
];
const DAYS_SHORT = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];

/** Date -> 'YYYY-MM-DD' in the user's local timezone. */
export function toIsoDate(date) {
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, '0');
  const d = String(date.getDate()).padStart(2, '0');
  return `${y}-${m}-${d}`;
}

/** Today as 'YYYY-MM-DD'. */
export function todayIso() {
  return toIsoDate(new Date());
}

/** 'YYYY-MM-DD' -> Date at local midnight (or null when malformed). */
export function fromIsoDate(iso) {
  const parts = String(iso || '').split('-').map(Number);
  const [y, m, d] = parts;
  if (!y || !m || !d) return null;
  const date = new Date(y, m - 1, d);
  return Number.isNaN(date.getTime()) ? null : date;
}

/** ISO date strings compare correctly as plain strings. */
export function isFutureIso(iso) {
  return String(iso) > todayIso();
}

/**
 * Friendly label: Today / Yesterday / weekday / '6 Oct' / '6 Oct 2025'.
 * @param {string} iso 'YYYY-MM-DD'
 * @param {Date} [now]
 */
export function formatSmallWinDate(iso, now = new Date()) {
  const date = fromIsoDate(iso);
  if (!date) return '';

  const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  const diffDays = Math.round((today.getTime() - date.getTime()) / 86400000);

  if (diffDays === 0) return 'Today';
  if (diffDays === 1) return 'Yesterday';
  if (diffDays > 1 && diffDays < 7) return DAYS_SHORT[date.getDay()];
  if (date.getFullYear() === now.getFullYear()) {
    return `${date.getDate()} ${MONTHS_SHORT[date.getMonth()]}`;
  }
  return `${date.getDate()} ${MONTHS_SHORT[date.getMonth()]} ${date.getFullYear()}`;
}

/** Unix ms -> '6 Oct 2026, 14:32' (used for created/modified metadata). */
export function formatSmallWinTimestamp(ms) {
  if (!ms) return '';
  const d = new Date(ms);
  if (Number.isNaN(d.getTime())) return '';
  const hh = String(d.getHours()).padStart(2, '0');
  const mm = String(d.getMinutes()).padStart(2, '0');
  return `${d.getDate()} ${MONTHS_SHORT[d.getMonth()]} ${d.getFullYear()}, ${hh}:${mm}`;
}

// src/utils/storageQuota.js
// Shared storage-quota watcher. Any feature can call updateStorageUsage()
// after a mutation and subscribe() to react to low-space conditions.

const listeners = new Set();

/** @type {null | {usage:number, quota:number, remaining:number, ratio:number, level:'ok'|'low'|'critical'|'unknown'}} */
let lastSnapshot = null;

export const LOW_THRESHOLD = 0.75;
export const CRITICAL_THRESHOLD = 0.9;

export function levelForRatio(ratio) {
  if (!Number.isFinite(ratio) || ratio <= 0) return 'ok';
  if (ratio >= CRITICAL_THRESHOLD) return 'critical';
  if (ratio >= LOW_THRESHOLD) return 'low';
  return 'ok';
}

/** Read navigator.storage.estimate() and normalise the result. */
export async function measureStorage() {
  if (typeof navigator === 'undefined' || !navigator.storage || !navigator.storage.estimate) {
    return { usage: 0, quota: 0, remaining: 0, ratio: 0, level: 'unknown' };
  }
  try {
    const { usage = 0, quota = 0 } = await navigator.storage.estimate();
    const remaining = Math.max(0, quota - usage);
    const ratio = quota > 0 ? usage / quota : 0;
    return { usage, quota, remaining, ratio, level: levelForRatio(ratio) };
  } catch {
    return { usage: 0, quota: 0, remaining: 0, ratio: 0, level: 'unknown' };
  }
}

function emit(snapshot) {
  listeners.forEach((fn) => {
    try {
      fn(snapshot);
    } catch {
      /* a broken listener must never break a write */
    }
  });
}

/**
 * Re-measure and broadcast. Call after every successful mutation.
 * @returns {Promise<typeof lastSnapshot>}
 */
export async function updateStorageUsage() {
  lastSnapshot = await measureStorage();
  emit(lastSnapshot);
  return lastSnapshot;
}

/** @returns {typeof lastSnapshot} */
export function getLastStorageSnapshot() {
  return lastSnapshot;
}

/** Subscribe to quota updates. Fires immediately with the last snapshot if we have one. */
export function subscribeStorage(listener) {
  listeners.add(listener);
  if (lastSnapshot) listener(lastSnapshot);
  return () => listeners.delete(listener);
}

/** Human-readable recommendations for the current level. */
export function storageAdvice(level) {
  if (level === 'critical') {
    return 'Storage is nearly full. Delete old wins or export and remove entries you no longer need.';
  }
  if (level === 'low') {
    return 'Storage is filling up. Consider removing unused names or older wins you no longer need.';
  }
  return '';
}

export function formatBytes(bytes) {
  if (!bytes) return '0 MB';
  const mb = bytes / (1024 * 1024);
  if (mb < 1) return `${(bytes / 1024).toFixed(0)} KB`;
  if (mb < 1024) return `${mb.toFixed(1)} MB`;
  return `${(mb / 1024).toFixed(2)} GB`;
}

// src/utils/useStorageQuota.js
// React binding for the shared storage-quota watcher.

import { useEffect, useState } from 'react';
import { getLastStorageSnapshot, subscribeStorage } from './storageQuota';

/**
 * @returns {null | {usage:number, quota:number, remaining:number, ratio:number, level:string}}
 */
export function useStorageQuota() {
  const [snapshot, setSnapshot] = useState(() => getLastStorageSnapshot());

  useEffect(() => subscribeStorage(setSnapshot), []);

  return snapshot;
}

export default useStorageQuota;

// src/utils/securityGate.js
// Passcode lifecycle + in-memory key custody for the shared security gate.
//
// NOTE: if the host app already provides a shared security module, delete this
// file and re-point the imports in:
//   - src/utils/smallWinsStorage.js   (getActiveKey, isDryRun)
//   - src/components/security/SecurityGate.jsx
//
// Storage used here holds ONLY: salt, iteration count, verifier blob and a
// reminder timestamp. None of it reveals the passcode.

import {
  PBKDF2_ITERATIONS,
  SALT_BYTES,
  base64ToBytes,
  bytesToBase64,
  checkVerifier,
  deriveKey,
  makeVerifier,
  randomBytes,
} from './crypto';

// --- safe localStorage (private mode / disabled storage fallback) ---------

const memoryFallback = new Map();

function readRaw(key) {
  try {
    const value = localStorage.getItem(key);
    return value === null ? memoryFallback.get(key) ?? null : value;
  } catch {
    return memoryFallback.get(key) ?? null;
  }
}

function writeRaw(key, value) {
  memoryFallback.set(key, value);
  try {
    localStorage.setItem(key, value);
  } catch {
    /* quota / disabled - memory fallback already holds it */
  }
}

function removeRaw(key) {
  memoryFallback.delete(key);
  try {
    localStorage.removeItem(key);
  } catch {
    /* ignore */
  }
}

// --- dry-run namespace ----------------------------------------------------

let dryRun = false;

/** Read ?dryRun=true from the current URL. Call once at app boot. */
export function initDryRunFromLocation() {
  try {
    const params = new URLSearchParams(window.location.search);
    dryRun = params.get('dryRun') === 'true';
  } catch {
    dryRun = false;
  }
  return dryRun;
}

export function isDryRun() {
  return dryRun;
}

export function setDryRun(value) {
  dryRun = !!value;
  activeKey = null;
}

function prefix() {
  return dryRun ? 'ummi.dryrun.' : 'ummi.';
}

const KEYS = {
  salt: () => `${prefix()}security.salt`,
  verifier: () => `${prefix()}security.verifier`,
  iterations: () => `${prefix()}security.iterations`,
  reminder: () => `${prefix()}security.reminderShownAt`,
};

// --- key custody ----------------------------------------------------------

/** @type {CryptoKey|null} */
let activeKey = null;
const subscribers = new Set();

function notify() {
  const unlocked = activeKey !== null;
  subscribers.forEach((fn) => {
    try {
      fn(unlocked);
    } catch {
      /* ignore */
    }
  });
}

/** Subscribe to lock/unlock transitions. */
export function subscribeLockState(fn) {
  subscribers.add(fn);
  return () => subscribers.delete(fn);
}

/**
 * The live decryption key. Only available while unlocked.
 * @throws when the vault is locked.
 */
export function getActiveKey() {
  if (!activeKey) {
    const err = new Error('Vault is locked');
    err.code = 'LOCKED';
    throw err;
  }
  return activeKey;
}

export function isUnlocked() {
  return activeKey !== null;
}

export function lock() {
  activeKey = null;
  notify();
}

// --- passcode lifecycle ---------------------------------------------------

export function hasPasscode() {
  return Boolean(readRaw(KEYS.salt()) && readRaw(KEYS.verifier()));
}

export function getStoredIterations() {
  return Number(readRaw(KEYS.iterations())) || PBKDF2_ITERATIONS;
}

/** First-run: create the passcode and unlock immediately. */
export async function createPasscode(passcode) {
  if (!passcode || passcode.length < 6) {
    throw new Error('Passcode must be at least 6 characters.');
  }
  const salt = randomBytes(SALT_BYTES);
  const iterations = PBKDF2_ITERATIONS;
  const key = await deriveKey(passcode, salt, iterations);
  const verifier = await makeVerifier(key);

  writeRaw(KEYS.salt(), bytesToBase64(salt));
  writeRaw(KEYS.iterations(), String(iterations));
  writeRaw(KEYS.verifier(), JSON.stringify(verifier));

  activeKey = key;
  notify();
  return true;
}

/** Derive the key for a passcode without changing lock state. */
async function deriveFromStored(passcode) {
  const saltB64 = readRaw(KEYS.salt());
  if (!saltB64) return null;
  return deriveKey(passcode, base64ToBytes(saltB64), getStoredIterations());
}

/** @returns {Promise<boolean>} true when the passcode is correct. */
export async function verifyPasscode(passcode) {
  const verifierRaw = readRaw(KEYS.verifier());
  if (!verifierRaw) return false;
  const key = await deriveFromStored(passcode);
  if (!key) return false;
  return checkVerifier(key, JSON.parse(verifierRaw));
}

/** Unlock and hold the key in memory. */
export async function unlock(passcode) {
  const verifierRaw = readRaw(KEYS.verifier());
  if (!verifierRaw) return false;
  const key = await deriveFromStored(passcode);
  if (!key) return false;
  const ok = await checkVerifier(key, JSON.parse(verifierRaw));
  if (ok) {
    activeKey = key;
    notify();
  }
  return ok;
}

/**
 * Change the passcode and re-encrypt every stored record.
 * Imports the storage layer lazily to avoid a circular dependency.
 */
export async function changePasscode(currentPasscode, newPasscode) {
  if (!newPasscode || newPasscode.length < 6) {
    throw new Error('New passcode must be at least 6 characters.');
  }
  const oldKey = await deriveFromStored(currentPasscode);
  if (!oldKey) throw new Error('Vault is not initialised.');

  const verifierRaw = readRaw(KEYS.verifier());
  const ok = await checkVerifier(oldKey, JSON.parse(verifierRaw));
  if (!ok) throw new Error('Current passcode is incorrect.');

  const salt = randomBytes(SALT_BYTES);
  const iterations = PBKDF2_ITERATIONS;
  const newKey = await deriveKey(newPasscode, salt, iterations);

  const { reencryptAll } = await import('./smallWinsStorage');
  await reencryptAll(oldKey, newKey);

  writeRaw(KEYS.salt(), bytesToBase64(salt));
  writeRaw(KEYS.iterations(), String(iterations));
  writeRaw(KEYS.verifier(), JSON.stringify(await makeVerifier(newKey)));

  activeKey = newKey;
  notify();
  return true;
}

// --- daily reminder -------------------------------------------------------

function isSameLocalDay(a, b) {
  const da = new Date(a);
  const db = new Date(b);
  return (
    da.getFullYear() === db.getFullYear() &&
    da.getMonth() === db.getMonth() &&
    da.getDate() === db.getDate()
  );
}

/** True at most once per calendar day, and only while no passcode exists. */
export function shouldShowDailyReminder(now = Date.now()) {
  if (hasPasscode()) return false;
  const last = Number(readRaw(KEYS.reminder())) || 0;
  return !isSameLocalDay(last, now);
}

export function markDailyReminderShown(now = Date.now()) {
  writeRaw(KEYS.reminder(), String(now));
}

/** Danger zone: drops credentials without touching encrypted data. */
export function clearCredentials() {
  removeRaw(KEYS.salt());
  removeRaw(KEYS.verifier());
  removeRaw(KEYS.iterations());
  activeKey = null;
  notify();
}

