// src/utils/smallWinsStorage.js
// IndexedDB CRUD + encryption for the two Small Wins stores.
//
// Design notes
// ------------
// * `smallWinsEntries` keeps id / date / createdAt / modifiedAt in the clear so
//   the by-date, by-created and by-modified indexes stay usable. The sensitive
//   fields (title, description, whoWith, and the canonical date) live inside an
//   encrypted `payload` blob.
// * `smallWinsPeople` stores only { id, payload }. Names are never written in
//   the clear; the people list is small enough to decrypt into memory once.
// * IMPORTANT: never await a non-IndexedDB promise inside a live transaction -
//   the transaction auto-commits. All crypto happens BEFORE opening the tx.

import { decryptJson, encryptJson } from './crypto';
import { getActiveKey, isDryRun } from './securityGate';
import { updateStorageUsage } from './storageQuota';
import { todayIso } from './formatSmallWinDate';

export const ENTRIES_STORE = 'smallWinsEntries';
export const PEOPLE_STORE = 'smallWinsPeople';

const SCHEMA_VERSION = 1;
const BASE_DB_NAME = 'ummi-db';

// --- connection -----------------------------------------------------------

function dbName() {
  return isDryRun() ? `${BASE_DB_NAME}-dryrun` : BASE_DB_NAME;
}

let dbPromise = null;

function createMissingStores(db) {
  if (!db.objectStoreNames.contains(ENTRIES_STORE)) {
    const store = db.createObjectStore(ENTRIES_STORE, { keyPath: 'id' });
    store.createIndex('by-date', 'date', { unique: false });
    store.createIndex('by-created', 'createdAt', { unique: false });
    store.createIndex('by-modified', 'modifiedAt', { unique: false });
  }
  if (!db.objectStoreNames.contains(PEOPLE_STORE)) {
    db.createObjectStore(PEOPLE_STORE, { keyPath: 'id' });
  }
}

/**
 * Open the shared app database, adding our stores if they are missing without
 * disturbing any other object store the host app owns.
 */
export function openDb() {
  if (dbPromise) return dbPromise;

  dbPromise = new Promise((resolve, reject) => {
    if (typeof indexedDB === 'undefined') {
      reject(new Error('IndexedDB is not available in this browser.'));
      return;
    }

    const first = indexedDB.open(dbName());

    first.onupgradeneeded = () => createMissingStores(first.result);
    first.onerror = () => reject(first.error);
    first.onsuccess = () => {
      const db = first.result;
      const complete =
        db.objectStoreNames.contains(ENTRIES_STORE) && db.objectStoreNames.contains(PEOPLE_STORE);
      if (complete) {
        resolve(db);
        return;
      }

      // Existing database from another feature: bump the version to add ours.
      const nextVersion = db.version + 1;
      db.close();

      const second = indexedDB.open(dbName(), nextVersion);
      second.onupgradeneeded = () => createMissingStores(second.result);
      second.onerror = () => reject(second.error);
      second.onsuccess = () => resolve(second.result);
    };
  }).catch((err) => {
    dbPromise = null;
    throw err;
  });

  return dbPromise;
}

/** Drop the cached connection (needed when toggling dry-run). */
export function resetDbConnection() {
  dbPromise = null;
}

function promisify(request) {
  return new Promise((resolve, reject) => {
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

/**
 * Run a synchronous IndexedDB body inside a transaction.
 * `fn` MUST perform its IDB calls synchronously (no awaiting foreign promises).
 */
function withStore(storeName, mode, fn) {
  return openDb().then(
    (db) =>
      new Promise((resolve, reject) => {
        let tx;
        try {
          tx = db.transaction(storeName, mode);
        } catch (err) {
          reject(err);
          return;
        }

        const store = tx.objectStore(storeName);
        let result;

        tx.oncomplete = () => resolve(result);
        tx.onerror = () => reject(tx.error);
        tx.onabort = () => reject(tx.error || new Error('Transaction aborted'));

        try {
          result = fn(store);
        } catch (err) {
          reject(err);
        }
      }),
  );
}

// --- ids & names ----------------------------------------------------------

export function makeId() {
  if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
    return crypto.randomUUID();
  }
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
    const r = (Math.random() * 16) | 0;
    const v = c === 'x' ? r : (r & 0x3) | 0x8;
    return v.toString(16);
  });
}

/** Trim + collapse internal whitespace. Preserves original casing. */
export function normaliseName(name) {
  return String(name || '')
    .replace(/\s+/g, ' ')
    .trim();
}

/** Comparison key for uniqueness: trimmed + lowercased. */
export function nameKey(name) {
  return normaliseName(name).toLowerCase();
}

// --- entry <-> record -----------------------------------------------------

function entryPayload(entry) {
  return {
    title: entry.title ?? '',
    description: entry.description ?? '',
    whoWith: Array.isArray(entry.whoWith) ? entry.whoWith : [],
    date: entry.date,
  };
}

async function sealEntry(entry, key) {
  return {
    id: entry.id,
    date: entry.date, // plaintext: required for the by-date index
    createdAt: entry.createdAt,
    modifiedAt: entry.modifiedAt,
    version: SCHEMA_VERSION,
    payload: await encryptJson(key, entryPayload(entry)),
  };
}

async function openEntry(record, key) {
  const payload = await decryptJson(key, record.payload);
  return {
    id: record.id,
    title: payload.title || '',
    description: payload.description || '',
    whoWith: Array.isArray(payload.whoWith) ? payload.whoWith : [],
    date: payload.date || record.date,
    createdAt: record.createdAt,
    modifiedAt: record.modifiedAt,
    version: record.version ?? SCHEMA_VERSION,
  };
}

function byDateDesc(a, b) {
  if (a.date !== b.date) return a.date < b.date ? 1 : -1;
  return (b.modifiedAt || 0) - (a.modifiedAt || 0);
}

// --- entries CRUD ---------------------------------------------------------

/**
 * Materialise a brand-new, unique, empty row.
 * The row exists immediately so the editor always autosaves into a real record.
 */
export async function createEntry({ date } = {}) {
  const key = getActiveKey();
  const now = Date.now();

  const entry = {
    id: makeId(),
    title: '',
    description: '',
    whoWith: [],
    date: date || todayIso(),
    createdAt: now,
    modifiedAt: now,
    version: SCHEMA_VERSION,
  };

  const record = await sealEntry(entry, key);
  await withStore(ENTRIES_STORE, 'readwrite', (store) => promisify(store.put(record)));
  await updateStorageUsage();

  return entry;
}

/** Insert or update one entry. Returns the persisted (modifiedAt-refreshed) entry. */
export async function saveEntry(entry) {
  const key = getActiveKey();
  const updated = { ...entry, modifiedAt: Date.now(), version: SCHEMA_VERSION };

  const record = await sealEntry(updated, key);
  await withStore(ENTRIES_STORE, 'readwrite', (store) => promisify(store.put(record)));
  await updateStorageUsage();

  return updated;
}

export async function getEntry(id) {
  const key = getActiveKey();
  const record = await withStore(ENTRIES_STORE, 'readonly', (store) => promisify(store.get(id)));
  if (!record) return null;
  try {
    return await openEntry(record, key);
  } catch {
    return null;
  }
}

/** All entries, decrypted and sorted newest-first. */
export async function listEntries() {
  const key = getActiveKey();
  const records = await withStore(ENTRIES_STORE, 'readonly', (store) => promisify(store.getAll()));

  const entries = [];
  for (const record of records) {
    try {
      entries.push(await openEntry(record, key));
    } catch {
      // Undecryptable rows are skipped rather than breaking the whole list.
    }
  }

  entries.sort(byDateDesc);
  return entries;
}

export async function deleteEntry(id) {
  await withStore(ENTRIES_STORE, 'readwrite', (store) => promisify(store.delete(id)));
  await updateStorageUsage();
  return true;
}

export async function countEntries() {
  return withStore(ENTRIES_STORE, 'readonly', (store) => promisify(store.count()));
}

// --- people CRUD ----------------------------------------------------------

function personPayload(person) {
  return {
    id: person.id,
    name: person.name,
    createdAt: person.createdAt,
    lastUsedAt: person.lastUsedAt,
  };
}

async function putPerson(person, key) {
  const record = { id: person.id, payload: await encryptJson(key, personPayload(person)) };
  await withStore(PEOPLE_STORE, 'readwrite', (store) => promisify(store.put(record)));
  return person;
}

/** All known people, most-recently-used first. */
export async function listPeople() {
  const key = getActiveKey();
  const records = await withStore(PEOPLE_STORE, 'readonly', (store) => promisify(store.getAll()));

  const people = [];
  for (const record of records) {
    try {
      people.push(await decryptJson(key, record.payload));
    } catch {
      // skip undecryptable rows
    }
  }

  people.sort((a, b) => (b.lastUsedAt || 0) - (a.lastUsedAt || 0) || a.name.localeCompare(b.name));
  return people;
}

/**
 * Create the person if the normalised name is new, otherwise refresh lastUsedAt
 * and adopt the latest casing.
 */
export async function upsertPerson(rawName) {
  const display = normaliseName(rawName);
  if (!display) return null;

  const key = getActiveKey();
  const target = nameKey(display);
  const records = await withStore(PEOPLE_STORE, 'readonly', (store) => promisify(store.getAll()));

  for (const record of records) {
    try {
      const existing = await decryptJson(key, record.payload);
      if (nameKey(existing.name) === target) {
        return putPerson({ ...existing, name: display, lastUsedAt: Date.now() }, key);
      }
    } catch {
      // ignore corrupt row
    }
  }

  const now = Date.now();
  return putPerson(
    { id: makeId(), name: display, createdAt: now, lastUsedAt: now },
    key,
  );
}

export async function deletePerson(id) {
  await withStore(PEOPLE_STORE, 'readwrite', (store) => promisify(store.delete(id)));
  await updateStorageUsage();
  return true;
}

/**
 * Remove people who are no longer referenced by any entry.
 * @returns {Promise<number>} how many were removed
 */
export async function pruneUnusedPeople(entries) {
  const used = new Set();
  (entries || []).forEach((entry) => {
    (entry.whoWith || []).forEach((name) => used.add(nameKey(name)));
  });

  const people = await listPeople();
  let removed = 0;
  for (const person of people) {
    if (!used.has(nameKey(person.name))) {
      await deletePerson(person.id); // eslint-disable-line no-await-in-loop
      removed += 1;
    }
  }
  return removed;
}

// --- re-encryption (passcode change) -------------------------------------

/** Decrypt everything with `oldKey` and rewrite it with `newKey`. */
export async function reencryptAll(oldKey, newKey) {
  const entryRecords = await withStore(ENTRIES_STORE, 'readonly', (store) => promisify(store.getAll()));
  const peopleRecords = await withStore(PEOPLE_STORE, 'readonly', (store) => promisify(store.getAll()));

  const nextEntries = [];
  for (const record of entryRecords) {
    const payload = await decryptJson(oldKey, record.payload); // eslint-disable-line no-await-in-loop
    nextEntries.push({ ...record, payload: await encryptJson(newKey, payload) }); // eslint-disable-line no-await-in-loop
  }

  const nextPeople = [];
  for (const record of peopleRecords) {
    const payload = await decryptJson(oldKey, record.payload); // eslint-disable-line no-await-in-loop
    nextPeople.push({ ...record, payload: await encryptJson(newKey, payload) }); // eslint-disable-line no-await-in-loop
  }

  await withStore(ENTRIES_STORE, 'readwrite', (store) => {
    nextEntries.forEach((record) => store.put(record));
    return null;
  });
  await withStore(PEOPLE_STORE, 'readwrite', (store) => {
    nextPeople.forEach((record) => store.put(record));
    return null;
  });
}

// --- export / danger zone -------------------------------------------------

/** Decrypted snapshot for a future export/share flow. */
export async function exportAll() {
  const [entries, people] = await Promise.all([listEntries(), listPeople()]);
  return { exportedAt: Date.now(), version: SCHEMA_VERSION, entries, people };
}

/** Wipe both stores. Requires an unlocked vault. */
export async function deleteAllData() {
  await withStore(ENTRIES_STORE, 'readwrite', (store) => promisify(store.clear()));
  await withStore(PEOPLE_STORE, 'readwrite', (store) => promisify(store.clear()));
  await updateStorageUsage();
}

// src/stores/smallWinsStore.js
// Zustand slice: view mode, entries, people, draft and auto-save status.

import { create } from 'zustand';
import * as storage from '../utils/smallWinsStorage';
import { debounce } from '../utils/debounce';
import { AUTOSAVE_DEBOUNCE_MS, AUTO_PRUNE_EMPTY_DRAFT, LIMITS } from '../data/SmallWinsData';
import { todayIso } from '../utils/formatSmallWinDate';

// --- pure helpers ---------------------------------------------------------

function mergeEntry(list, entry) {
  const idx = list.findIndex((e) => e.id === entry.id);
  if (idx === -1) return [entry, ...list];
  const next = list.slice();
  next[idx] = entry;
  return next;
}

function mergePerson(list, person) {
  const key = storage.nameKey(person.name);
  const idx = list.findIndex((p) => storage.nameKey(p.name) === key);
  if (idx === -1) return [person, ...list];
  const next = list.slice();
  next[idx] = person;
  return next;
}

/** Field-level dirty check against the last persisted snapshot. */
export function isDirty(draft, baseline) {
  if (!draft || !baseline) return false;
  return (
    draft.title !== baseline.title ||
    draft.description !== baseline.description ||
    draft.date !== baseline.date ||
    (draft.whoWith || []).join('\u0000') !== (baseline.whoWith || []).join('\u0000')
  );
}

function isEmptyDraft(draft) {
  if (!draft) return true;
  return (
    !draft.title.trim() &&
    !draft.description.trim() &&
    (draft.whoWith || []).length === 0
  );
}

function byDateDesc(a, b) {
  if (a.date !== b.date) return a.date < b.date ? 1 : -1;
  return (b.modifiedAt || 0) - (a.modifiedAt || 0);
}

/** Case-insensitive filter over title, description and people. */
export function filterEntries(entries, query) {
  const q = query.trim().toLowerCase();
  if (!q) return entries;
  return entries.filter((entry) => {
    if (entry.title.toLowerCase().includes(q)) return true;
    if (entry.description.toLowerCase().includes(q)) return true;
    return (entry.whoWith || []).some((name) => name.toLowerCase().includes(q));
  });
}

export function sortEntries(entries) {
  return entries.slice().sort(byDateDesc);
}

const INITIAL = {
  status: 'idle', // idle | loading | ready | error
  error: null,
  entries: [],
  people: [],
  view: 'overview', // overview | editor
  tab: 'wins', // wins | why
  selectedId: null,
  draft: null,
  baseline: null,
  saveStatus: 'idle', // idle | saving | saved | error
  query: '',
  busy: false,
};

// --- store ----------------------------------------------------------------

export const useSmallWinsStore = create((set, get) => {
  /** Persist the current draft immediately. */
  const flushSave = async () => {
    const { draft } = get();
    if (!draft) return;

    set({ saveStatus: 'saving' });
    try {
      const saved = await storage.saveEntry(draft);
      set((state) => ({
        entries: sortEntries(mergeEntry(state.entries, saved)),
        draft: state.draft && state.draft.id === saved.id ? saved : state.draft,
        baseline: state.draft && state.draft.id === saved.id ? saved : state.baseline,
        saveStatus: 'saved',
        error: null,
      }));
    } catch (err) {
      set({ saveStatus: 'error', error: String(err?.message || err) });
    }
  };

  const scheduleSave = debounce(() => {
    flushSave();
  }, AUTOSAVE_DEBOUNCE_MS);

  return {
    ...INITIAL,

    // --- lifecycle -------------------------------------------------------

    /** Load everything from IndexedDB. Safe to call repeatedly. */
    init: async () => {
      if (get().status === 'loading') return;
      set({ status: 'loading', error: null });
      try {
        const [entries, people] = await Promise.all([
          storage.listEntries(),
          storage.listPeople(),
        ]);
        set({ entries, people, status: 'ready' });
      } catch (err) {
        set({ status: 'error', error: String(err?.message || err) });
      }
    },

    /** Re-read from storage without flashing the loading state. */
    refresh: async () => {
      try {
        const [entries, people] = await Promise.all([
          storage.listEntries(),
          storage.listPeople(),
        ]);
        set({ entries, people, status: 'ready', error: null });
      } catch (err) {
        set({ error: String(err?.message || err) });
      }
    },

    /** Drop all decrypted state (called on lock). */
    reset: () => {
      scheduleSave.cancel();
      set({ ...INITIAL });
    },

    // --- navigation ------------------------------------------------------

    setTab: (tab) => set({ tab }),
    setQuery: (query) => set({ query }),
    setSaveStatus: (saveStatus) => set({ saveStatus }),

    // --- editor ----------------------------------------------------------

    /** Create a unique empty row first, then open the editor. */
    openCreate: async () => {
      set({ busy: true, error: null });
      try {
        const entry = await storage.createEntry({ date: todayIso() });
        set((state) => ({
          entries: sortEntries(mergeEntry(state.entries, entry)),
          selectedId: entry.id,
          draft: entry,
          baseline: entry,
          view: 'editor',
          saveStatus: 'idle',
          busy: false,
        }));
        return entry.id;
      } catch (err) {
        set({ busy: false, error: String(err?.message || err) });
        return null;
      }
    },

    openEntry: (id) => {
      const entry = get().entries.find((e) => e.id === id);
      if (!entry) return;
      set({
        selectedId: id,
        draft: { ...entry },
        baseline: entry,
        view: 'editor',
        saveStatus: 'idle',
      });
    },

    /** Merge a patch into the draft and schedule a debounced write. */
    updateDraft: (patch) => {
      const { draft } = get();
      if (!draft) return;
      const next = { ...draft, ...patch };
      set((state) => ({
        draft: next,
        entries: sortEntries(mergeEntry(state.entries, next)),
        saveStatus: 'saving',
      }));
      scheduleSave();
    },

    /** Add a person to whoWith (unique, case-insensitive) and remember the name. */
    addWhoWith: async (rawName) => {
      const { draft } = get();
      if (!draft) return;

      const display = storage.normaliseName(rawName);
      if (!display) return;

      const key = storage.nameKey(display);
      const already = (draft.whoWith || []).some((n) => storage.nameKey(n) === key);
      if (already) return;
      if ((draft.whoWith || []).length >= LIMITS.whoWithMax) return;

      get().updateDraft({ whoWith: [...(draft.whoWith || []), display] });

      try {
        const person = await storage.upsertPerson(display);
        if (person) set((state) => ({ people: mergePerson(state.people, person) }));
      } catch {
        // A failed people write must not lose the entry edit.
      }
    },

    removeWhoWith: (name) => {
      const { draft } = get();
      if (!draft) return;
      const key = storage.nameKey(name);
      get().updateDraft({
        whoWith: (draft.whoWith || []).filter((n) => storage.nameKey(n) !== key),
      });
    },

    deleteEntry: async (id) => {
      scheduleSave.cancel();
      try {
        await storage.deleteEntry(id);
        set((state) => ({
          entries: state.entries.filter((e) => e.id !== id),
          view: 'overview',
          draft: null,
          baseline: null,
          selectedId: null,
          saveStatus: 'idle',
        }));
      } catch (err) {
        set({ error: String(err?.message || err) });
      }
    },

    /** @returns {Promise<boolean>} false when the caller must confirm a discard. */
    requestClose: async () => {
      const { draft, baseline } = get();
      if (draft && isDirty(draft, baseline)) return false;
      await get().saveAndClose();
      return true;
    },

    /** Flush pending writes, optionally prune an untouched empty row, then leave. */
    saveAndClose: async () => {
      scheduleSave.flush();
      if (scheduleSave.pending()) return; // flush already triggered an async write

      const { draft } = get();
      if (draft) {
        try {
          const saved = await storage.saveEntry(draft);
          set((state) => ({ entries: sortEntries(mergeEntry(state.entries, saved)) }));
        } catch {
          // keep the in-memory copy; the user can retry on next open
        }

        if (AUTO_PRUNE_EMPTY_DRAFT && isEmptyDraft(draft)) {
          try {
            await storage.deleteEntry(draft.id);
            set((state) => ({ entries: state.entries.filter((e) => e.id !== draft.id) }));
          } catch {
            // ignore
          }
        }
      }

      set({
        view: 'overview',
        draft: null,
        baseline: null,
        selectedId: null,
        saveStatus: 'idle',
      });
    },

    /** Revert to the last persisted snapshot and leave. */
    discardAndClose: async () => {
      scheduleSave.cancel();
      const { draft, baseline } = get();

      if (draft && AUTO_PRUNE_EMPTY_DRAFT && isEmptyDraft(draft)) {
        try {
          await storage.deleteEntry(draft.id);
          set((state) => ({ entries: state.entries.filter((e) => e.id !== draft.id) }));
        } catch {
          // ignore
        }
      } else if (draft && baseline && draft.id === baseline.id) {
        set((state) => ({ entries: sortEntries(mergeEntry(state.entries, baseline)) }));
      }

      set({
        view: 'overview',
        draft: null,
        baseline: null,
        selectedId: null,
        saveStatus: 'idle',
      });
    },
  };
});

export default useSmallWinsStore;

// src/components/security/SecurityGate.jsx
// Shared passcode gate. Children mount ONLY once the vault is unlocked, so
// `useEffect` data loading inside children never runs while locked.

import { useCallback, useEffect, useState } from 'react';
import {
  changePasscode,
  createPasscode,
  hasPasscode,
  isDryRun,
  isUnlocked,
  lock,
  markDailyReminderShown,
  shouldShowDailyReminder,
  unlock,
} from '../../utils/securityGate';
import { cryptoAvailable } from '../../utils/crypto';
import './securityGate.scss';

const MIN_LENGTH = 6;

export default function SecurityGate({ children, activityName = 'this activity', onLocked }) {
  const [mode, setMode] = useState('loading'); // loading | create | locked | open | unsupported
  const [passcode, setPasscode] = useState('');
  const [confirmPasscode, setConfirmPasscode] = useState('');
  const [newPasscode, setNewPasscode] = useState('');
  const [error, setError] = useState('');
  const [busy, setBusy] = useState(false);
  const [showReminder, setShowReminder] = useState(false);
  const [showChange, setShowChange] = useState(false);

  useEffect(() => {
    if (!cryptoAvailable()) {
      setMode('unsupported');
      return;
    }
    if (isUnlocked()) {
      setMode('open');
      return;
    }
    setMode(hasPasscode() ? 'locked' : 'create');
    if (shouldShowDailyReminder()) {
      setShowReminder(true);
      markDailyReminderShown();
    }
  }, []);

  const resetFields = useCallback(() => {
    setPasscode('');
    setConfirmPasscode('');
    setNewPasscode('');
    setError('');
  }, []);

  const handleCreate = async (event) => {
    event.preventDefault();
    setError('');

    if (passcode.length < MIN_LENGTH) {
      setError(`Use at least ${MIN_LENGTH} characters.`);
      return;
    }
    if (passcode !== confirmPasscode) {
      setError('The two passcodes do not match.');
      return;
    }

    setBusy(true);
    try {
      await createPasscode(passcode);
      resetFields();
      setMode('open');
    } catch (err) {
      setError(String(err?.message || err));
    } finally {
      setBusy(false);
    }
  };

  const handleUnlock = async (event) => {
    event.preventDefault();
    setError('');
    setBusy(true);
    try {
      const ok = await unlock(passcode);
      if (!ok) {
        setError('That passcode is not correct.');
        setPasscode('');
        return;
      }
      resetFields();
      setMode('open');
    } catch (err) {
      setError(String(err?.message || err));
    } finally {
      setBusy(false);
    }
  };

  const handleChangePasscode = async (event) => {
    event.preventDefault();
    setError('');
    setBusy(true);
    try {
      await changePasscode(passcode, newPasscode);
      resetFields();
      setShowChange(false);
    } catch (err) {
      setError(String(err?.message || err));
    } finally {
      setBusy(false);
    }
  };

  const handleLock = () => {
    lock();
    if (onLocked) onLocked();
    setMode(hasPasscode() ? 'locked' : 'create');
    resetFields();
  };

  if (mode === 'loading') {
    return (
      <div className="security-gate security-gate--centered" role="status" aria-live="polite">
        <p>Checking security…</p>
      </div>
    );
  }

  if (mode === 'unsupported') {
    return (
      <div className="security-gate security-gate--centered" role="alert">
        <h2>Browser not supported</h2>
        <p>
          {activityName} needs Web Crypto to encrypt your data. Please update your browser or open
          the app in a modern browser.
        </p>
      </div>
    );
  }

  if (mode === 'create') {
    return (
      <div className="security-gate security-gate--centered">
        <form className="security-gate__card" onSubmit={handleCreate}>
          <h2 className="security-gate__title">Create your passcode</h2>
          <p className="security-gate__lede">
            Your wins are encrypted with this passcode before they are stored on this device.
          </p>

          <div className="security-gate__warning" role="note">
            If you forget your passcode, your data cannot be recovered. There is no reset.
          </div>

          {showReminder && (
            <p className="security-gate__reminder">
              Reminder: {activityName} is currently unsecured. Setting a passcode protects it.
            </p>
          )}

          <label className="security-gate__label" htmlFor="sg-create-pass">
            Passcode
          </label>
          <input
            id="sg-create-pass"
            className="security-gate__input"
            type="password"
            autoComplete="new-password"
            value={passcode}
            onChange={(e) => setPasscode(e.target.value)}
            minLength={MIN_LENGTH}
            required
          />

          <label className="security-gate__label" htmlFor="sg-create-confirm">
            Confirm passcode
          </label>
          <input
            id="sg-create-confirm"
            className="security-gate__input"
            type="password"
            autoComplete="new-password"
            value={confirmPasscode}
            onChange={(e) => setConfirmPasscode(e.target.value)}
            minLength={MIN_LENGTH}
            required
          />

          {error && <p className="security-gate__error" role="alert">{error}</p>}

          <button className="security-gate__submit" type="submit" disabled={busy}>
            {busy ? 'Creating…' : 'Create and unlock'}
          </button>

          {isDryRun() && <p className="security-gate__dryrun">Dry-run mode — no real data is touched.</p>}
        </form>
      </div>
    );
  }

  if (mode === 'locked') {
    return (
      <div className="security-gate security-gate--centered">
        <form className="security-gate__card" onSubmit={handleUnlock}>
          <h2 className="security-gate__title">Unlock {activityName}</h2>

          <div className="security-gate__warning" role="note">
            Forgotten passcodes cannot be recovered. Your data would be permanently lost.
          </div>

          <label className="security-gate__label" htmlFor="sg-unlock-pass">
            Passcode
          </label>
          <input
            id="sg-unlock-pass"
            className="security-gate__input"
            type="password"
            autoComplete="current-password"
            value={passcode}
            onChange={(e) => setPasscode(e.target.value)}
            autoFocus
            required
          />

          {error && <p className="security-gate__error" role="alert">{error}</p>}

          <button className="security-gate__submit" type="submit" disabled={busy}>
            {busy ? 'Unlocking…' : 'Unlock'}
          </button>

          {isDryRun() && <p className="security-gate__dryrun">Dry-run mode — no real data is touched.</p>}
        </form>
      </div>
    );
  }

  // mode === 'open'
  return (
    <div className="security-gate security-gate--open">
      <div className="security-gate__bar">
        <span className="security-gate__lock" aria-label="Locked with passcode">
          🔒
        </span>
        {isDryRun() && <span className="security-gate__badge">Dry run</span>}
        <button type="button" className="security-gate__link" onClick={() => setShowChange((v) => !v)}>
          Change passcode
        </button>
        <button type="button" className="security-gate__link" onClick={handleLock}>
          Lock
        </button>
      </div>

      {showChange && (
        <form className="security-gate__card security-gate__card--inline" onSubmit={handleChangePasscode}>
          <label className="security-gate__label" htmlFor="sg-current-pass">
            Current passcode
          </label>
          <input
            id="sg-current-pass"
            className="security-gate__input"
            type="password"
            autoComplete="current-password"
            value={passcode}
            onChange={(e) => setPasscode(e.target.value)}
            required
          />

          <label className="security-gate__label" htmlFor="sg-new-pass">
            New passcode
          </label>
          <input
            id="sg-new-pass"
            className="security-gate__input"
            type="password"
            autoComplete="new-password"
            minLength={MIN_LENGTH}
            value={newPasscode}
            onChange={(e) => setNewPasscode(e.target.value)}
            required
          />

          {error && <p className="security-gate__error" role="alert">{error}</p>}

          <div className="security-gate__actions">
            <button className="security-gate__submit" type="submit" disabled={busy}>
              {busy ? 'Updating…' : 'Update passcode'}
            </button>
            <button
              type="button"
              className="security-gate__cancel"
              onClick={() => {
                setShowChange(false);
                resetFields();
              }}
            >
              Cancel
            </button>
          </div>
        </form>
      )}

      <div className="security-gate__content">{children}</div>
    </div>
  );
}

